syntax:
class Base {
    public:
        virtual void pureVirtual() = 0;  // Pure virtual function
        virtual void virtualFunc() { /* Base implementation */ }
        Base() { virtualFunc();  // Implementation note: This calls Base::virtualFunc(), not any derived override
            // Calling pureVirtual() here would cause undefined behavior
        }
};

class Derived : public Base {
    public:
        void virtualFunc() override { /* Derived implementation */ }  // This won't be called from Base constructor
};

code_example:
#include <iostream>

class Base {
public:
    virtual void virtualFunc() { std::cout << "Base::virtualFunc" << std::endl; }
    Base() {
        std::cout << "Base constructor: ";
        virtualFunc();  // This will call Base::virtualFunc(), even if overridden
    }
};

class Derived : public Base {
public:
    void virtualFunc() override { std::cout << "Derived::virtualFunc" << std::endl; }
    Derived() {
        std::cout << "Derived constructor" << std::endl;
    }
};

int main() {
    Derived d;  // Output: Base constructor: Base::virtualFunc then Derived constructor
    return 0;
}
